 return <Modal title={conversation?'Add a follow-up message':'Bring a message into BentaBuddy'} subtitle="Paste customer text. It stays in your local database." onClose={onClose}><form onSubmit={submit} className="form"><div className="info-box"><MessageCircle size={18}/><span>{demo?'You’re adding a fictional conversation to the demo workspace.':'Manual import · This is not a live Facebook connection.'}</span></div><label>Customer name<input required maxLength={100} value={name} disabled={!!conversation} onChange={e=>setName(e.target.value)} placeholder="e.g. Mika Santos"/></label>{!conversation&&<label>Update an existing order? <span className="optional">Optional</span><select value={order} onChange={e=>{setOrder(e.target.value);const o=orders.find(o=>o.id===e.target.value);if(o)setName(o.customer_name)}}><option value="">No, start a new conversation</option>{orders.filter(o=>o.state!=='canceled'&&o.fulfillment!=='fulfilled').map(o=><option key={o.id} value={o.id}>{o.number} · {o.customer_name}</option>)}</select></label>}<label>Customer message<textarea required rows={6} maxLength={16000} value={text} onChange={e=>setText(e.target.value)} placeholder="Ate, pa-order 2 dozen cheese pandesal bukas, pickup 8am po…"/></label><button className="text-button" type="button" onClick={()=>{setName('Demo customer');setText('Ate, pa-order 2 dozen cheese pandesal bukas, pickup 8am po. Gawin na lang 3 dozen, 9am na lang. Salamat!')}}>Use a sample Taglish message <Sparkles size={14}/></button><div className="modal-actions"><Button type="button" variant="secondary" onClick={onClose}>Cancel</Button><Button disabled={busy||!text.trim()||!name.trim()}>{busy?<Loader2 size={16} className="spin"/>:<Plus size={16}/>}Save message</Button></div></form></Modal>
